const fs = require('fs');
const path = require('path');
const express = require('express');
const { UPLOAD_DIR } = require('../../middlewares/upload.middleware');
const { verifyMediaSignature } = require('../../utils/signedUrl');
const ApiError = require('../../utils/ApiError');

const router = express.Router();

// Only file names generated by our upload middleware are accepted
const FILENAME_PATTERN = /^\d+-[a-f0-9]{16}\.[a-z0-9]{2,5}$/;

router.get('/:filename', (req, res, next) => {
  const { filename } = req.params;
  const { exp, sig } = req.query;

  if (!FILENAME_PATTERN.test(filename)) {
    return next(new ApiError(404, 'File not found'));
  }
  if (!verifyMediaSignature(filename, exp, sig)) {
    return next(new ApiError(403, 'Link is invalid or has expired'));
  }

  const filePath = path.join(UPLOAD_DIR, filename);
  if (!fs.existsSync(filePath)) {
    return next(new ApiError(404, 'File not found'));
  }

  res.set({
    'Cache-Control': 'private, max-age=300',
    'X-Content-Type-Options': 'nosniff',
  });
  return res.sendFile(filePath);
});

module.exports = router;